import java.util.*;

class MapSum {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        int prefixSum;
    }

    private final TrieNode root;
    private final Map<String, Integer> values;

    public MapSum() {
        root = new TrieNode();
        values = new HashMap<>();
    }

    public void insert(String key, int val) {
        int delta = val - values.getOrDefault(key, 0);
        values.put(key, val);

        TrieNode node = root;
        for (char c : key.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
            node.prefixSum += delta;
        }
    }

    public int sum(String prefix) {
        TrieNode node = root;
        for (char c : prefix.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                return 0;
            }
            node = node.children[idx];
        }
        return node.prefixSum;
    }
}

import java.util.*;

class MapSum {
    private final Map<String, Integer> values;
    private final Map<String, Integer> prefixSums;

    public MapSum() {
        values = new HashMap<>();
        prefixSums = new HashMap<>();
    }

    public void insert(String key, int val) {
        int delta = val - values.getOrDefault(key, 0);
        values.put(key, val);
        for (int end = 1; end <= key.length(); end++) {
            String prefix = key.substring(0, end);
            prefixSums.put(prefix, prefixSums.getOrDefault(prefix, 0) + delta);
        }
    }

    public int sum(String prefix) {
        return prefixSums.getOrDefault(prefix, 0);
    }
}

import java.util.*;

class MapSum {
    private final Map<String, Integer> values;

    public MapSum() {
        values = new HashMap<>();
    }

    public void insert(String key, int val) {
        values.put(key, val);
    }

    public int sum(String prefix) {
        int total = 0;
        for (Map.Entry<String, Integer> entry : values.entrySet()) {
            if (entry.getKey().startsWith(prefix)) {
                total += entry.getValue();
            }
        }
        return total;
    }
}

import java.util.*;

class MapSum {
    private final TreeMap<String, Integer> values;

    public MapSum() {
        values = new TreeMap<>();
    }

    public void insert(String key, int val) {
        values.put(key, val);
    }

    public int sum(String prefix) {
        int total = 0;
        String upper = prefix + "{";
        for (int value : values.subMap(prefix, true, upper, false).values()) {
            total += value;
        }
        return total;
    }
}
